import {downloadBlob} from './ui.js?v=5';
export function patternSnapshot(field,size=480){field.draw();const c=document.createElement('canvas');c.width=size;c.height=Math.round(size*field.h/field.w);const ctx=c.getContext('2d');ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(field.canvas,0,0,c.width,c.height);return c.toDataURL('image/webp',.8)}
export function exportPNG(field,transparent=false){field.draw();const c=document.createElement('canvas');c.width=field.canvas.width;c.height=field.canvas.height;const ctx=c.getContext('2d');if(!transparent){ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();ctx.fillRect(0,0,c.width,c.height)}ctx.drawImage(field.canvas,0,0);c.toBlob(blob=>{if(blob)downloadBlob(blob,transparent?'RMS-resonance-transparent.png':'RMS-resonance.png')},'image/png')}
export function patternSVG(field){const p=field.particles,density=field.density??1,detail=field.detail??1,color=field.color;const grains=[];for(let i=0;i<p.length;i+=4){if(p[i+2]>density)continue;const size=(1.25+p[i+2]*.75)*detail;grains.push(`<rect x="${p[i].toFixed(1)}" y="${p[i+1].toFixed(1)}" width="${size.toFixed(1)}" height="${size.toFixed(1)}" opacity="${p[i+3].toFixed(2)}"/>`)}return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${field.w} ${field.h}"><title>RMS · 生成式共振纹样</title><g fill="${color}">${grains.join('')}</g></svg>`}
export function exportSVG(field){downloadBlob(new Blob([patternSVG(field)],{type:'image/svg+xml'}),'RMS-resonance.svg')}
